 /**
  * 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。
  */
 @Transactional public AccountView account(AccountRequest r){var a=new CloudAccount(r.organizationCode(),r.accountCode(),r.provider(),r.name());em.persist(a);audit("FINOPS_ACCOUNT","登记云账号",a.accountCode,a.provider);return view(a);}/**
                                                                                                                                                                                                                                        * 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。
                                                                                                                                                                                                                                        */
@Transactional public AccountView activate(Long id){var a=account(id);if(!"DRAFT".equals(a.status))throw conflict("只有草稿云账号可以启用");a.status="ACTIVE";audit("FINOPS_ACCOUNT","启用云账号",a.accountCode,a.provider);return view(a);}/**
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    * 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    */
@Transactional public BudgetView budget(BudgetRequest r){if(r.warningPercent()<1||r.warningPercent()>100)throw bad("预算预警比例必须在1到100之间");var b=new CloudBudget(r.organizationCode(),r.costCenter(),r.fiscalMonth(),r.budgetAmount(),r.warningPercent());em.persist(b);audit("FINOPS_BUDGET","建立成本预算",r.costCenter(),r.fiscalMonth());return view(b);}
 /**
  * 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。
  */
 @Transactional public CostResult ingest(Long accountId,CostRequest r){var a=account(accountId);if(!"ACTIVE".equals(a.status))throw conflict("云账号未启用");long dup=em.createQuery("select count(c) from CloudCostRecord c where c.providerLineId=:n",Long.class).setParameter("n",r.providerLineId()).getSingleResult();if(dup>0)throw conflict("云账单明细已存在");var c=new CloudCostRecord(r.providerLineId(),accountId,r.serviceCode(),r.resourceId(),r.costCenter(),r.amount(),r.baselineAmount(),r.tagged(),r.usageDate());em.persist(c);List<String> created=new ArrayList<>();String month=r.usageDate().toString().substring(0,7);var budget=em.createQuery("select b from CloudBudget b where b.organizationCode=:o and b.costCenter=:cc and b.fiscalMonth=:m and b.status='ACTIVE'",CloudBudget.class).setParameter("o",a.organizationCode).setParameter("cc",r.costCenter()).setParameter("m",month).getResultStream().findFirst().orElse(null);if(budget!=null){double spent=em.createQuery("select coalesce(sum(x.amount),0) from CloudCostRecord x where x.costCenter=:cc and substring(cast(x.usageDate as string),1,7)=:m",Double.class).setParameter("cc",r.costCenter()).setParameter("m",month).getSingleResult();if(spent>=budget.budgetAmount*budget.warningPercent/100d){createAlert("BUDGET-"+budget.id,a.organizationCode,"BUDGET","HIGH","成本中心 "+r.costCenter()+" 已达到预算阈值");created.add("BUDGET");}}if(r.baselineAmount()>0&&r.amount()>r.baselineAmount()*1.5){createAlert("ANOMALY-"+r.providerLineId(),a.organizationCode,"ANOMALY","HIGH","资源 "+r.resourceId()+" 成本较基线增长超过50%");created.add("ANOMALY");}if(!r.tagged()){createAlert("TAG-"+r.providerLineId(),a.organizationCode,"TAG_GOVERNANCE","MEDIUM","资源 "+r.resourceId()+" 缺少治理标签");created.add("TAG_GOVERNANCE");}audit("FINOPS_COST","采集云成本",r.providerLineId(),"amount="+r.amount());return new CostResult(view(c),created);}
 /**
  * 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。
  */
 @Transactional public RecommendationView recommend(Long accountId,RecommendationRequest r){var a=account(accountId);if(!"ACTIVE".equals(a.status))throw conflict("云账号未启用");var x=new OptimizationRecommendation(r.recommendationNo(),accountId,r.resourceId(),r.actionType(),r.estimatedMonthlySavings());em.persist(x);audit("FINOPS_OPTIMIZATION","创建优化建议",x.recommendationNo,x.actionType);return view(x);}/**
                                                                                                                                                                                                                                                                                                                                                                                                                * 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。
                                                                                                                                                                                                                                                                                                                                                                                                                */
@Transactional public RecommendationView approve(Long id){var x=recommendation(id);if(!"PROPOSED".equals(x.status))throw conflict("建议状态不可批准");x.status="APPROVED";audit("FINOPS_OPTIMIZATION","批准优化建议",x.recommendationNo,"saving="+x.estimatedMonthlySavings);return view(x);}/**
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               * 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               */
@Transactional public RecommendationView realize(Long id,RealizeRequest r){var x=recommendation(id);if(!"APPROVED".equals(x.status))throw conflict("只有已批准建议可以登记落地");x.actualMonthlySavings=r.actualMonthlySavings();x.executionNote=r.note();x.status="REALIZED";audit("FINOPS_OPTIMIZATION","登记优化收益",x.recommendationNo,r.note());return view(x);}
 /**
  * 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。
  */
 private void createAlert(String no,String o,String t,String s,String d){long exists=em.createQuery("select count(a) from CostAlert a where a.alertNo=:n",Long.class).setParameter("n",no).getSingleResult();if(exists==0)em.persist(new CostAlert(no,o,t,s,d));}/**
                                                                                                                                                                                                                                                                  * 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。
                                                                                                                                                                                                                                                                  */
private List<AccountView>accounts(String o){return em.createQuery("select a from CloudAccount a where a.organizationCode=:o order by a.createdAt desc",CloudAccount.class).setParameter("o",o).getResultList().stream().map(this::view).toList();}/**
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    * 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    */
private List<CostView>costs(String o){return em.createQuery("select c from CloudCostRecord c where c.accountId in(select a.id from CloudAccount a where a.organizationCode=:o) order by c.ingestedAt desc",CloudCostRecord.class).setParameter("o",o).setMaxResults(100).getResultList().stream().map(this::view).toList();}/**
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                * 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                */
private List<AlertView>alerts(String o){return em.createQuery("select a from CostAlert a where a.organizationCode=:o order by a.createdAt desc",CostAlert.class).setParameter("o",o).getResultList().stream().map(this::view).toList();}/**
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        * 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        */
private List<RecommendationView>recommendations(String o){return em.createQuery("select r from OptimizationRecommendation r where r.accountId in(select a.id from CloudAccount a where a.organizationCode=:o) order by r.id desc",OptimizationRecommendation.class).setParameter("o",o).getResultList().stream().map(this::view).toList();}/**
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   * 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   */
private CloudAccount account(Long id){var x=em.find(CloudAccount.class,id);if(x==null)throw missing("云账号不存在");return x;}/**
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           * 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           */
private OptimizationRecommendation recommendation(Long id){var x=em.find(OptimizationRecommendation.class,id);if(x==null)throw missing("优化建议不存在");return x;}/**
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       * 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       */
private void audit(String m,String a,String n,String d){logs.save(new AuditLog(m,a,n,"finops-domain",d));}/**
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 * 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 */
private ResponseStatusException bad(String m){return new ResponseStatusException(HttpStatus.BAD_REQUEST,m);}/**
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             * 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             */
private ResponseStatusException conflict(String m){return new ResponseStatusException(HttpStatus.CONFLICT,m);}/**
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           * 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           */
